@layer components {
  .profile-card {
    border-width: var(--shelf-borderWidth-md);
    border-style: solid;
    border-color: var(--shelf-profileCard-borderColor);
    background-color: var(--shelf-profileCard-bgColor);
    padding: var(--shelf-space-md);
  }

  .profile-card-title {
    color: var(--shelf-profileCard-title-fgColor);
    font-size: var(--shelf-fontSize-lg);
  }

  .profile-card-subtitle {
    color: var(--shelf-profileCard-subtitle-fgColor);
    font-size: var(--shelf-fontSize-sm);
  }

  .profile-card-skeleton-bar {
    background-color: var(--shelf-skeleton-bgColor);
    height: var(--shelf-size-skeletonBar);
    border-radius: var(--shelf-borderRadius-sm);
    animation: shimmer var(--shelf-duration-shimmer) var(--shelf-easing-linear) infinite;
  }

  .profile-card-skeleton-bar--narrow {
    width: var(--shelf-size-skeletonBarNarrow);
  }

  @keyframes shimmer {
    0% {
      opacity: 1;
    }
    50% {
      opacity: var(--shelf-opacity-shimmerMin);
    }
    100% {
      opacity: 1;
    }
  }
}
